import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiItem","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/item/index.md","filePath":"en/modules/item/index.md","lastUpdated":0}`),a={name:`en/modules/item/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakiitem" tabindex="-1">EmakiItem <a class="header-anchor" href="#emakiitem" aria-label="Permalink to “EmakiItem”">​</a></h1><p>EmakiItem provides lightweight custom items, stable item IDs, sets, trigger actions, auto update, and PlaceholderAPI support. It is often the starting point for equipment progression.</p><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to “Module facts”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>2.8.0</code></td></tr><tr><td>Main command</td><td><code>/emakiitem</code></td></tr><tr><td>Alias</td><td><code>/ei</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependencies</td><td>EmakiAttribute, EmakiSkills, MythicMobs, PlaceholderAPI</td></tr><tr><td>Permissions</td><td><code>emakiitem.use</code>, <code>emakiitem.give</code>, <code>emakiitem.browse</code>, <code>emakiitem.inspect</code>, <code>emakiitem.update</code>, <code>emakiitem.reload</code>, <code>emakiitem.debug</code>, <code>emakiitem.admin</code></td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>Listing and giving items, inspecting the held item and its components, refreshing items and sets, reload and debug.</td></tr><tr><td><a href="./definitions.html">Definitions and Sets</a></td><td>The fields of <code>items/*.yml</code> and <code>sets/*.yml</code>, and how an item ID produces an ItemStack.</td></tr><tr><td><a href="./browser.html">Browser GUI</a></td><td>The two-level browser opened by <code>/ei browse</code>, <code>pack.yml</code> pack metadata, and slot types.</td></tr><tr><td><a href="./triggers.html">Triggers</a></td><td>Running actions on interact, attack, projectile, block, and drop events.</td></tr><tr><td><a href="./update.html">Update Strategy</a></td><td>Bringing items players already hold up to a changed definition.</td></tr><tr><td><a href="./repair.html">Repair System</a></td><td>The disabled state at zero durability and the material/currency repair flow.</td></tr><tr><td><a href="./integration.html">Cross-Module Integration</a></td><td>Item source syntax when Attribute, Forge, Strengthen, Gem, Skills, or Cooking reference an item.</td></tr><tr><td><a href="./mythic.html">MythicMobs Integration</a></td><td>Dropping EmakiItem items from MythicMobs <code>Drops</code>.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Main-hand update, redraw, repair, durability, and vanilla data component actions.</td></tr><tr><td><a href="./api.html">API</a></td><td>Creating, identifying, and querying items through <code>EmakiItemApi</code>.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>Bukkit events and interception points across the item flow.</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core capabilities”">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Stable item ID</td><td>Uses config IDs instead of display names.</td></tr><tr><td>Item components</td><td>Configures material, name, lore, model, enchants, flags, durability, and more.</td></tr><tr><td>Attribute output</td><td>Can provide attribute payloads to Attribute.</td></tr><tr><td>Skill binding</td><td>Can expose skills or skill unlock data.</td></tr><tr><td>Set system</td><td>Grants attributes, skills, or lore based on equipped piece count.</td></tr><tr><td>Triggers</td><td>Runs actions on interaction, combat, projectile, block, drop, and other events.</td></tr><tr><td>Auto update</td><td>Refreshes item state on login, hand switch, inventory click, pickup, and similar cases.</td></tr><tr><td>Repair system</td><td>Items enter a disabled state at zero durability and can be repaired with materials or currency.</td></tr><tr><td>Browser GUI</td><td>A two-level GUI browses every item by pack and takes pieces directly.</td></tr><tr><td>ID aliases and migration</td><td>Maps renamed item IDs and can migrate configs and player inventories in bulk.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to “Default runtime folder”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiItem/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── id_aliases.yml</span></span>
<span class="line"><span>├── items/</span></span>
<span class="line"><span>├── sets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>items/</code> defines items, <code>sets/</code> defines item sets, <code>gui/</code> holds the repair and two browser templates (<code>repair_gui.yml</code>, <code>pack_browser_gui.yml</code>, <code>item_browser_gui.yml</code>), and <code>id_aliases.yml</code> stores renamed item ID mappings.</p><p>Every subdirectory of <code>items/</code> is an item pack and may carry a <code>pack.yml</code> defining its icon in the browser; see <a href="./browser.html">Browser GUI</a>.</p><h2 id="main-configuration" tabindex="-1">Main configuration <a class="header-anchor" href="#main-configuration" aria-label="Permalink to “Main configuration”">​</a></h2><p><code>config.yml</code> contains only global settings; item behavior lives in the individual definition files.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>Current module version</td><td>Marks the default config structure; manual edits are discouraged.</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>Language file ID, matching <code>lang/&lt;language&gt;.yml</code>.</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>Whether to release default sample data such as <code>items/</code> and <code>sets/</code>. This does not control <code>config.yml</code> or language files.</td></tr><tr><td><code>data_directories.max_depth</code></td><td>int</td><td><code>2</code></td><td>Maximum subdirectory scan depth for <code>items/</code> and <code>sets/</code>, counting the data directory itself. <code>1</code> reads only the root, <code>2</code> allows one level of subdirectories, <code>3</code> allows two. Directories beyond the limit are skipped with a console warning; the minimum value is <code>1</code>.</td></tr><tr><td><code>set_bonus.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Whether the set bonus system is enabled.</td></tr><tr><td><code>set_bonus.refresh_triggers.join</code></td><td>boolean</td><td><code>true</code></td><td>Refresh set state when a player joins.</td></tr><tr><td><code>set_bonus.refresh_triggers.held_change</code></td><td>boolean</td><td><code>true</code></td><td>Refresh when the held item changes.</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_click</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on inventory click.</td></tr><tr><td><code>set_bonus.refresh_triggers.inventory_drag</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on inventory drag.</td></tr><tr><td><code>set_bonus.refresh_triggers.pickup</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on item pickup.</td></tr><tr><td><code>set_bonus.refresh_triggers.interact</code></td><td>boolean</td><td><code>true</code></td><td>Refresh on interaction.</td></tr><tr><td><code>set_bonus.refresh_triggers.command</code></td><td>boolean</td><td><code>true</code></td><td>Allow refresh when related commands run.</td></tr><tr><td><code>mythicmobs.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Master switch for the MythicMobs integration.</td></tr><tr><td><code>mythicmobs.drops.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Whether the MythicMobs custom drop is registered.</td></tr><tr><td><code>mythicmobs.drops.names</code></td><td>list</td><td><code>emakiitem</code>, <code>ei_item</code></td><td>Recognized drop names; falls back to the defaults when empty.</td></tr><tr><td><code>item_state.clamp</code></td><td>boolean</td><td><code>true</code></td><td>Whether written values are clamped to the min/max declared in <code>fields</code>. Only overflow protection remains when disabled.</td></tr><tr><td><code>item_state.fill_defaults</code></td><td>boolean</td><td><code>true</code></td><td>Whether <code>add</code> uses the <code>fields</code> default as the starting value when the field is absent. A missing field is rejected outright when disabled.</td></tr><tr><td><code>item_state.fields</code></td><td>map</td><td><code>{}</code></td><td>Field declarations keyed by state key name, carrying <code>type</code>, <code>default</code>, <code>min</code>, <code>max</code>, and <code>thresholds</code>. Only numeric types support min/max and thresholds; undeclared fields are unaffected by clamping, defaults, and thresholds.</td></tr><tr><td><code>item_state.migrations</code></td><td>map</td><td><code>{}</code></td><td>Migration steps per schema version. Each step declares <code>from</code>/<code>to</code> and may <code>rename</code>, <code>retype</code>, or <code>drop</code> fields. Empty means no migration.</td></tr><tr><td><code>item_state.preservation.verify_rebuild</code></td><td>boolean</td><td><code>true</code></td><td>Verify state survives an item rebuild and backfill from the pre-rebuild snapshot when it is missing.</td></tr><tr><td><code>item_state.preservation.repair_on_pickup</code></td><td>boolean</td><td><code>false</code></td><td>Repair damaged state metadata on pickup.</td></tr><tr><td><code>item_state.preservation.repair_on_drop</code></td><td>boolean</td><td><code>false</code></td><td>Repair damaged state metadata on drop.</td></tr><tr><td><code>item_state.preservation.repair_on_trade</code></td><td>boolean</td><td><code>false</code></td><td>Repair damaged state metadata on trade.</td></tr><tr><td><code>item_state.preservation.repair_on_container_transfer</code></td><td>boolean</td><td><code>false</code></td><td>Repair damaged state metadata on container transfer.</td></tr><tr><td><code>item_state.preservation.repair_on_join</code></td><td>boolean</td><td><code>false</code></td><td>Repair damaged state metadata when a player joins.</td></tr><tr><td><code>item_state.derivation.enabled</code></td><td>boolean</td><td><code>false</code></td><td>Master switch for state-change-driven derived refreshes.</td></tr><tr><td><code>item_state.derivation.refresh_lore</code></td><td>boolean</td><td><code>true</code></td><td>Refresh set lore during a derived refresh.</td></tr><tr><td><code>item_state.derivation.refresh_attributes</code></td><td>boolean</td><td><code>true</code></td><td>Sync attributes during a derived refresh.</td></tr><tr><td><code>item_state.derivation.scan_holder</code></td><td>boolean</td><td><code>true</code></td><td>Allow scanning online players to locate the item when holder information is missing.</td></tr><tr><td><code>item_state.derivation.max_depth</code></td><td>int</td><td><code>2</code></td><td>Maximum recursion depth for derived refreshes and threshold rewards, blocking self-triggering loops.</td></tr><tr><td><code>proficiency_guard.dedupe_per_event</code></td><td>boolean</td><td><code>true</code></td><td>Dispatch one item definition at most once per event.</td></tr><tr><td><code>proficiency_guard.max_dispatches_per_event</code></td><td>int</td><td><code>0</code></td><td>Maximum dispatches per event; <code>0</code> means unlimited.</td></tr><tr><td><code>proficiency_guard.same_target_cooldown_seconds</code></td><td>int</td><td><code>0</code></td><td>Cooldown in seconds against the same target; <code>0</code> means no cooldown.</td></tr><tr><td><code>proficiency_guard.daily_soft_cap</code></td><td>int</td><td><code>0</code></td><td>Daily soft cap; <code>0</code> means no cap. Counts live in memory, reset on the server&#39;s local date change, and do not survive a restart.</td></tr><tr><td><code>proficiency_guard.decay_factor</code></td><td>double</td><td><code>1.0</code></td><td>Decay factor once the soft cap is exceeded, in (0, 1]; <code>1.0</code> rejects outright past the cap.</td></tr><tr><td><code>proficiency_guard.decay_minimum_ratio</code></td><td>double</td><td><code>0.0</code></td><td>Lower bound for the decayed pass probability, in [0, 1].</td></tr><tr><td><code>proficiency_guard.guarded_triggers</code></td><td>list</td><td><code>damage_dealt</code>, <code>kill_entity</code>, <code>kill_player</code></td><td>Triggers governed by this section.</td></tr></tbody></table><p><code>set_bonus.refresh_triggers</code> controls set state refreshing, while item auto-update is controlled separately by <code>update.triggers</code> in an item definition; neither overrides the other.</p><p><code>item_state.*</code> applies to the <code>emaki:item_state</code> PDC partition and is read and written by the <code>item_state_*</code> action stages and the API. The whole section is additive: leaving it untouched keeps the previous behavior. <code>proficiency_guard.*</code> applies to slot dispatch for <code>damage_dealt</code>, <code>kill_entity</code>, and <code>kill_player</code>; everything except <code>dedupe_per_event</code> defaults to disabled or unlimited.</p><h2 id="typical-item-lifecycle" tabindex="-1">Typical item lifecycle <a class="header-anchor" href="#typical-item-lifecycle" aria-label="Permalink to “Typical item lifecycle”">​</a></h2><ol><li>Define item IDs, material, name, lore, and components in <code>items/</code>.</li><li>Optionally add Attribute stats, Skills, or set info.</li><li>An administrator gives out the item.</li><li>A player uses the item.</li><li>Item automatically refreshes its state when triggered.</li><li>Forge / Strengthen / Gem can continue writing their own layers on top.</li><li>CoreLib rebuilds the final presentation.</li></ol><h2 id="relations-with-other-modules" tabindex="-1">Relations with other modules <a class="header-anchor" href="#relations-with-other-modules" aria-label="Permalink to “Relations with other modules”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Integration</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>Item writes base or set attributes.</td></tr><tr><td>EmakiSkills</td><td>Item writes equipment skill IDs and forced equipment triggers. The PDC keys are owned by a standalone protocol module and do not depend on EmakiSkills being enabled.</td></tr><tr><td>EmakiForge</td><td>Forge can modify items created by EmakiItem.</td></tr><tr><td>EmakiStrengthen</td><td>Strengthen can strengthen EmakiItem equipment.</td></tr><tr><td>EmakiGem</td><td>Gem can add sockets and inlay gems onto EmakiItem equipment.</td></tr><tr><td>MythicMobs</td><td>MythicMobs mobs can drop EmakiItem items through <code>Drops</code>.</td></tr></tbody></table>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};